import test from 'node:test';import assert from 'node:assert/strict';
import {repairLockMetadata} from './policy.mjs';import {writeRepair} from './repair.mjs';
const before={dependencies:{zod:'^3.0.0'},devDependencies:{vitest:'^4.1.10'}},after={...before,devDependencies:{vitest:'^4.1.11'}};
const runtime={version:'1.5.0',resolved:'https://registry.npmjs.org/jsonschema/-/jsonschema-1.5.0.tgz',integrity:'sha512-YWJjZA==',inBundle:true,extraneous:true};
const old={lockfileVersion:3,packages:{'':before,'node_modules/jsonschema':runtime}},fresh={lockfileVersion:3,packages:{'':after,'node_modules/jsonschema':{...runtime}}};delete fresh.packages['node_modules/jsonschema'].extraneous;
const files=['package.json','package-lock.json'].map(filename=>({filename,status:'modified'}));
test('restores only harmless runtime metadata while preserving tool update',()=>{const r=repairLockMetadata(before,after,old,fresh,files);assert.deepEqual(r.lock.packages['node_modules/jsonschema'],runtime);assert.deepEqual(r.lock.packages[''],after);assert.equal(fresh.packages['node_modules/jsonschema'].extraneous,undefined);});
for(const [key,value]of [['version','1.6.0'],['integrity','sha512-evil'],['resolved','https://evil.test/a'],['dependencies',{bad:'1.0.0'}]])test('refuses changed '+key,()=>{const b=structuredClone(fresh);b.packages['node_modules/jsonschema'][key]=value;assert.throws(()=>repairLockMetadata(before,after,old,b,files));});
test('refuses repairs around changed scripts',()=>assert.throws(()=>repairLockMetadata(before,{...after,scripts:{install:'bad'}},old,fresh,files)));
test('refuses malformed flags',()=>{const b=structuredClone(fresh);b.packages['node_modules/jsonschema'].extraneous='true';assert.throws(()=>repairLockMetadata(before,after,old,b,files));});
const head='a'.repeat(40),base='b'.repeat(40),commit='c'.repeat(40),repo='instancelabs/cdki-license-service',branch='dependabot/npm_and_yarn/vitest-4.1.11';
function mock(race=false){const calls=[];let reads=0;return{calls,request:async(path,method='GET',body)=>{calls.push({path,method,body});if(path.endsWith('/heads/'+branch))return{object:{sha:race&&++reads>1?commit:head}};if(path.endsWith('/heads/main'))return{object:{sha:base}};if(path.endsWith('/git/commits/'+head))return{tree:{sha:base}};return{sha:commit};}};}
test('writer touches exactly one lockfile path, retains parents and never force pushes',async()=>{const m=mock();await writeRepair({...m,repo,branch,head,base,content:'{}\n'});assert.deepEqual(m.calls.find(c=>c.path.endsWith('/git/trees')).body.tree,[{path:'package-lock.json',mode:'100644',type:'blob',sha:commit}]);assert.deepEqual(m.calls.find(c=>c.path.endsWith('/git/commits')).body.parents,[head]);assert.deepEqual(m.calls.at(-1).body,{sha:commit,force:false});});
test('writer stops on a moved PR before changing branch',async()=>{const m=mock(true);await assert.rejects(writeRepair({...m,repo,branch,head,base,content:'{}'}));assert.equal(m.calls.some(c=>c.method==='PATCH'),false);});
test('writer cannot target main',async()=>{const m=mock();await assert.rejects(writeRepair({...m,repo,branch:'main',head,base,content:'{}'}));assert.equal(m.calls.length,0);});
